+        margin: 0 0 12px;
+        font-size: clamp(1.6rem, 4vw, 2.2rem);
+        line-height: 1.15;
+      }
+
+      .lead {
+        margin: 0 0 28px;
+        color: var(--muted);
+        max-width: 40ch;
+      }
+
+      form {
+        display: grid;
+        gap: 20px;
+      }
+
+      .form-field {
+        padding: 18px;
+        border: 1px solid var(--border);
+        border-radius: 18px;
+        background: rgba(7, 11, 24, 0.35);
+      }
+
+      .checkbox-row {
+        display: flex;
+        gap: 14px;
+        align-items: flex-start;
+      }
+
+      .checkbox-row input {
+        inline-size: 1.15rem;
+        block-size: 1.15rem;
+        margin: 0.2rem 0 0;
+        accent-color: var(--accent);
+        flex: 0 0 auto;
+      }
+
+      .checkbox-copy {
+        display: grid;
+        gap: 6px;
+      }
+
+      label {
+        font-weight: 600;
+        color: var(--text);
+      }
+
+      .helper {
+        margin: 0;
+        color: var(--muted);
+        font-size: 0.95rem;
+      }
+
+      .error {
+        margin: 0;
+        color: var(--error);
+        font-size: 0.95rem;
+      }
+
+      .is-hidden {
+        display: none;
+      }
+
+      .actions {
+        display: flex;
+        gap: 12px;
+        align-items: center;
+        justify-content: flex-end;
+      }
+
+      button {
+        border: 0;
+        border-radius: 999px;
+        padding: 0.95rem 1.35rem;
+        font: inherit;
+        font-weight: 700;
+        color: #071020;
+        background: linear-gradient(180deg, var(--accent-strong), var(--accent));
+        box-shadow: 0 10px 24px rgba(124, 156, 255, 0.28);
+        cursor: pointer;
+      }
+
+      button:hover {
+        filter: brightness(1.04);
+      }
+
+      .status {
+        min-height: 1.5em;
+        margin: 0;
+        color: var(--muted);
+      }
+
+      @media (max-width: 480px) {
+        .card {
+          padding: 24px;
+          border-radius: 20px;
+        }
+
+        .actions {
+          justify-content: stretch;
+        }
+
+        button {
+          width: 100%;
+        }
+      }
+
+      @media (forced-colors: active) {
+        :root {
+          --accent: Highlight;
+          --accent-strong: Highlight;
+          --border: GrayText;
+          --border-strong: Highlight;
+          --text: CanvasText;
+          --muted: CanvasText;
+          --error: LinkText;
+        }
+
+        .card,
+        .form-field {
+          border: 1px solid ButtonText;
+        }
+
+        button {
+          forced-color-adjust: auto;
+          border: 1px solid ButtonText;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <div id="app"></div>
+
+    <script>
+      function App() {
+        return `
+          <main class="page">
+            <section class="card" aria-labelledby="page-title">
+              <h1 id="page-title">Terms of Use Consent</h1>
+              <p class="lead">Review the terms, confirm your agreement, and continue.</p>
+
+              <form id="consent-form" novalidate>
+                <div class="form-field">
+                  <div class="checkbox-row">
+                    <input
+                      id="agree-terms"
+                      name="agreeTerms"
+                      type="checkbox"
+                      required
+                      aria-describedby="agree-help agree-error"
+                    >
+                    <div class="checkbox-copy">
+                      <label for="agree-terms">I agree to the Terms of Use</label>
+                      <p id="agree-help" class="helper">Required to continue.</p>
+                      <p id="agree-error" class="error is-hidden" role="alert">Error: Please agree to the Terms of Use to continue.</p>
+                    </div>
+                  </div>
+                </div>
+
+                <div class="actions">
+                  <button type="submit">Continue</button>
+                </div>
+
+                <p id="form-status" class="status" aria-live="polite"></p>
+              </form>
+            </section>
+          </main>
+        `;
+      }
+
+      function mount() {
+        document.getElementById('app').innerHTML = App();
+
+        const form = document.getElementById('consent-form');
+        const checkbox = document.getElementById('agree-terms');
+        const error = document.getElementById('agree-error');
+        const status = document.getElementById('form-status');
+
+        form.addEventListener('submit', function (event) {
+          event.preventDefault();
+
+          if (!checkbox.checked) {
+            checkbox.setAttribute('aria-invalid', 'true');
+            error.classList.remove('is-hidden');
+            status.textContent = '';
+            checkbox.focus();
+            return;
+          }
+
+          checkbox.removeAttribute('aria-invalid');
+          error.classList.add('is-hidden');
+          status.textContent = 'Agreement recorded. You can proceed.';
+        });
+
+        checkbox.addEventListener('change', function () {
+          if (checkbox.checked) {
+            checkbox.removeAttribute('aria-invalid');
+            error.classList.add('is-hidden');
+          }
+        });
+      }
+
+      mount();
+    </script>
+  </body>
+</html>
*** End Patch
