const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');
const axeSource = require('axe-core').source;
(async() => {
  const browser = await chromium.launch({headless: true});
  const page = await browser.newPage();
  const html = fs.readFileSync(path.join(process.cwd(), 'index.html'), 'utf8');
  await page.setContent(html, { waitUntil: 'load' });
  await page.addScriptTag({ content: axeSource });
  const results = await page.evaluate(async () => await window.axe.run());
  const violations = results.violations.filter(v => !v.tags?.includes('best-practice'));
  console.log(JSON.stringify(violations.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })), null, 2));
  await browser.close();
  process.exit(violations.length ? 1 : 0);
})().catch(err => { console.error(err); process.exit(1); });
